import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const ROOT=process.cwd();
const VERSION='V1.3.0';
const pagePath='src/pages/TeacherMonthlyReportPrintPage.tsx';
const cssPath='src/teacher-monthly-report-print.css';
const logoPath='public/brand/kojac-wordmark.png';
const topAsset='public/brand/monthly-report-corner-top-left.png';
const bottomAsset='public/brand/monthly-report-corner-bottom-right.png';
const marker='monthly-report-corner-top-left.png';

function fail(msg){console.error(`\n[FAIL] ${msg}`);process.exit(1)}
function full(p){return resolve(ROOT,p)}
function read(p){return readFileSync(full(p),'utf8')}
function write(p,s){mkdirSync(dirname(full(p)),{recursive:true});writeFileSync(full(p),s,'utf8')}
function count(s,needle){return s.split(needle).length-1}

console.log(`KOJAC Teacher Monthly Report Visual Fix ${VERSION}`);
console.log('Scope: monthly report PDF/print layout only. Slip Honor / Invoice / Kwitansi / database protected.');

for(const p of [pagePath,cssPath,logoPath]) if(!existsSync(full(p))) fail(`File existing wajib tidak ditemukan: ${p}`);
let page=read(pagePath);
let css=read(cssPath);

for(const a of [
  'export function TeacherMonthlyReportPrintPage()',
  'monthly-print-page',
  'LAPORAN BULANAN PENGAJAR',
  'CATATAN MANAJEMEN',
  'DETAIL KEGIATAN MENGAJAR'
]) if(!page.includes(a)) fail(`Anchor print page tidak cocok: ${a}`);
if(!css.includes('.monthly-print-page')||!css.includes('@media print')) fail('Anchor CSS print monthly report tidak cocok.');

const already=page.includes('monthly-print-brand') && page.includes('monthly-print-summary-table') && css.includes(marker);
if(!already){
  const oldHeader=`<header className="monthly-print-header">
          <div><p>KOJAC</p><span>KUUHAKU ONLINE JAPANESE CLASS</span></div>
          <div><h1>LAPORAN BULANAN PENGAJAR</h1><strong>{detail.report_number||'DRAFT'}</strong></div>
        </header>`;
  const newHeader=`<header className="monthly-print-header">
          <div className="monthly-print-brand"><img src="/brand/kojac-wordmark.png" alt="KOJAC"/><span>Kuuhaku Online Japanese Class</span></div>
          <div className="monthly-print-title"><h1>LAPORAN BULANAN PENGAJAR</h1><strong>No. Dokumen: {detail.report_number||'DRAFT'}</strong></div>
        </header>`;
  if(!page.includes(oldHeader)) fail('Anchor header halaman 1 berbeda dari baseline yang diaudit.');
  page=page.replace(oldHeader,newHeader);

  const oldHeader2=`<header className="monthly-print-header"><div><p>KOJAC</p><span>KUUHAKU ONLINE JAPANESE CLASS</span></div><div><h1>DETAIL KEGIATAN MENGAJAR</h1><strong>{detail.report_number||'DRAFT'}</strong></div></header>`;
  const newHeader2=`<header className="monthly-print-header"><div className="monthly-print-brand"><img src="/brand/kojac-wordmark.png" alt="KOJAC"/><span>Kuuhaku Online Japanese Class</span></div><div className="monthly-print-title"><h1>DETAIL KEGIATAN MENGAJAR</h1><strong>No. Dokumen: {detail.report_number||'DRAFT'}</strong></div></header>`;
  if(!page.includes(oldHeader2)) fail('Anchor header halaman detail berbeda dari baseline yang diaudit.');
  page=page.replace(oldHeader2,newHeader2);

  const oldIdentity=`<div className="monthly-print-identity">
          <div><span>Nama</span><strong>{s.teacher.teacher_name}</strong></div>
          <div><span>Team</span><strong>{s.teacher.team_name||'Pengajar KOJAC'}</strong></div>
          <div><span>Periode</span><strong>{fmt(detail.period_start)} – {fmt(detail.period_end)}</strong></div>
          <div><span>Status</span><strong>{detail.status==='finalized'?'Final':'Draft'}</strong></div>
        </div>`;
  const newIdentity=`<div className="monthly-print-identity">
          <div><span>Nama</span><strong>{s.teacher.teacher_name}</strong></div>
          <div><span>Periode</span><strong>{fmt(detail.period_start)} – {fmt(detail.period_end)}</strong></div>
          <div><span>Team</span><strong>{s.teacher.team_name||'Pengajar KOJAC'}</strong></div>
          <div><span>Status</span><strong>{detail.status==='finalized'?'Final':'Draft'}</strong></div>
        </div>`;
  if(!page.includes(oldIdentity)) fail('Anchor identitas pengajar berbeda dari baseline yang diaudit.');
  page=page.replace(oldIdentity,newIdentity);

  const replacements=[
    ['<h2>RINGKASAN</h2>\n        <table><tbody>','<h2>RINGKASAN</h2>\n        <table className="monthly-print-summary-table"><tbody>'],
    ['<h2>REKAP PER KELAS</h2>\n        <table>','<h2>REKAP PER KELAS</h2>\n        <table className="monthly-print-class-table">'],
    ['<h2>RINGKASAN HONOR</h2>\n          <table><tbody>','<h2>RINGKASAN HONOR</h2>\n          <table className="monthly-print-honor-table"><tbody>']
  ];
  for(const [a,b] of replacements){if(!page.includes(a))fail(`Anchor tabel tidak ditemukan: ${a.split('\n')[0]}`);page=page.replace(a,b)}
}

write(pagePath,page);
write(cssPath,`@page{size:A4;margin:0}
.monthly-print-screen{min-height:100vh;background:#eee7e8;padding:24px}
.monthly-print-toolbar{max-width:794px;margin:0 auto 14px;display:flex;justify-content:space-between;gap:12px}
.monthly-print-toolbar a,.monthly-print-toolbar button{display:inline-flex;align-items:center;gap:7px;border:1px solid #d7c9cc;border-radius:10px;background:#fff;color:#5d464d;padding:10px 14px;text-decoration:none;font-size:13px;font-weight:800;cursor:pointer}
.monthly-print-doc{display:grid;gap:24px;justify-content:center}
.monthly-print-page{position:relative;width:794px;min-height:1123px;background:#fff;padding:48px 58px 38px;box-sizing:border-box;overflow:hidden;font-family:Arial,Helvetica,sans-serif;color:#171113;display:flex;flex-direction:column}
.monthly-print-page>*:not(.monthly-print-accent){position:relative;z-index:1}
.monthly-print-page::before{content:"";position:absolute;inset:190px 180px 210px;background:url('/brand/kojac-symbol.png') center/contain no-repeat;opacity:.028;pointer-events:none;z-index:0}
.monthly-print-accent{position:absolute;width:118px;height:118px;background-repeat:no-repeat;background-size:contain;background-position:center;pointer-events:none;z-index:2}
.monthly-print-accent.top{left:0;top:0;background-image:url('/brand/monthly-report-corner-top-left.png')}
.monthly-print-accent.bottom{right:0;bottom:0;background-image:url('/brand/monthly-report-corner-bottom-right.png')}
.monthly-print-header{display:grid;grid-template-columns:220px minmax(0,1fr);align-items:center;gap:30px;margin:8px 0 26px;padding:0 2px 15px;border-bottom:2px solid #8b1e33}
.monthly-print-brand{display:flex;align-items:center;gap:10px;min-width:0}
.monthly-print-brand img{display:block;width:154px;max-height:52px;object-fit:contain;object-position:left center}
.monthly-print-brand span{display:none}
.monthly-print-title{text-align:right;min-width:0}
.monthly-print-header h1{margin:0 0 7px;color:#7d1b2d;font-size:25px;line-height:1.15;letter-spacing:.015em;font-weight:900}
.monthly-print-header strong{display:block;font-size:12px;line-height:1.4;color:#3f3034;font-weight:700;overflow-wrap:anywhere}
.monthly-print-identity{display:grid;grid-template-columns:1fr 1fr;column-gap:38px;row-gap:10px;margin-bottom:22px;padding:15px 17px;border:1px solid #e4d5d9;background:rgba(250,247,248,.82);border-radius:8px}
.monthly-print-identity div{display:grid;grid-template-columns:74px 10px minmax(0,1fr);align-items:start;gap:4px;font-size:12px;line-height:1.45}
.monthly-print-identity div::after{content:""}
.monthly-print-identity span{font-weight:800;color:#6d5259}
.monthly-print-identity span::after{content:" :";float:right;color:#8b1e33}
.monthly-print-identity strong{font-size:12px;font-weight:700;color:#171113}
.monthly-print-page h2{font-size:14px;line-height:1.25;margin:20px 0 8px;color:#7b192b;font-weight:900;letter-spacing:.025em;border-bottom:1px solid #d8c6cb;padding-bottom:5px}
.monthly-print-page table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:11.5px;line-height:1.35;background:rgba(255,255,255,.92)}
.monthly-print-page th,.monthly-print-page td{border:1px solid #b9a8ad;padding:9px 10px;text-align:left;vertical-align:middle;overflow-wrap:anywhere}
.monthly-print-page th{background:#7f1d31;color:#fff;font-size:11px;font-weight:800;text-align:center}
.monthly-print-page tbody tr:nth-child(even) td{background:rgba(250,247,248,.76)}
.monthly-print-summary-table td:nth-child(odd),.monthly-print-honor-table td:nth-child(odd){font-weight:800;color:#60494f;background:#faf7f8;width:28%}
.monthly-print-summary-table td:nth-child(even),.monthly-print-honor-table td:nth-child(even){font-weight:700;width:22%}
.monthly-print-class-table th:nth-child(1){width:46%}.monthly-print-class-table th:nth-child(2),.monthly-print-class-table th:nth-child(3){width:16%}.monthly-print-class-table th:nth-child(4){width:22%}
.monthly-print-class-table td:not(:first-child){text-align:center}
.monthly-print-notes{min-height:42px;border:1px solid #cdbdc1;border-radius:6px;padding:10px 12px;font-size:11.5px;line-height:1.5;white-space:pre-wrap;background:rgba(250,247,248,.72)}
.monthly-print-page footer{margin-top:auto;padding:22px 120px 4px;text-align:center;display:grid;gap:3px;line-height:1.18}
.monthly-print-page footer span{font-size:12px;font-weight:700;color:#544247}
.monthly-print-page footer strong{font-size:14px;color:#2b2023}
.monthly-print-page footer small{font-size:11px;color:#6c565c}
.monthly-print-sessions{padding-top:48px}
.monthly-print-sessions .monthly-print-header{margin-bottom:20px}
.session-table{font-size:10.5px!important;line-height:1.4!important}
.session-table th,.session-table td{padding:8px 9px!important;vertical-align:top!important}
.session-table th:nth-child(1){width:15%}.session-table th:nth-child(2){width:21%}.session-table th:nth-child(3){width:32%}.session-table th:nth-child(4){width:32%}
.session-table tbody tr{break-inside:avoid;page-break-inside:avoid}
@media print{
  html,body,#root{margin:0!important;padding:0!important;width:210mm!important;background:#fff!important}
  .sidebar,.mobile-nav-topbar,.monthly-print-toolbar{display:none!important}
  .main{margin:0!important;padding:0!important}
  .monthly-print-screen{padding:0!important;background:#fff!important}
  .monthly-print-doc{display:block!important}
  .monthly-print-page{width:210mm!important;min-height:297mm!important;height:auto!important;margin:0!important;box-shadow:none!important;break-after:page!important;page-break-after:always!important}
  .monthly-print-page:last-child{break-after:auto!important;page-break-after:auto!important}
  .monthly-print-accent{-webkit-print-color-adjust:exact;print-color-adjust:exact}
  .monthly-print-page th{-webkit-print-color-adjust:exact;print-color-adjust:exact}
}
@media(max-width:850px){.monthly-print-screen{padding:10px;overflow:auto}.monthly-print-toolbar{min-width:700px}}
`);
writeFileSync(full(topAsset),Buffer.from('','base64'));
writeFileSync(full(bottomAsset),Buffer.from('','base64'));

const finalPage=read(pagePath), finalCss=read(cssPath);
for(const [label,ok] of [
  ['logo KOJAC existing dipakai',finalPage.includes('/brand/kojac-wordmark.png')],
  ['header title class',finalPage.includes('monthly-print-title')],
  ['summary table class',finalPage.includes('monthly-print-summary-table')],
  ['honor table class',finalPage.includes('monthly-print-honor-table')],
  ['corner top asset',existsSync(full(topAsset))&&finalCss.includes('monthly-report-corner-top-left.png')],
  ['corner bottom asset',existsSync(full(bottomAsset))&&finalCss.includes('monthly-report-corner-bottom-right.png')],
  ['footer slogan Jepang',finalPage.includes('空白オンライン日本語クラス')],
  ['footer slogan Indonesia/English brand',finalPage.includes('Kuuhaku Online Japanese Class')],
  ['no unsupported replaceAll',!finalPage.includes('.replaceAll(')]
]) if(!ok) fail(`Verifikasi gagal: ${label}`);
if(count(finalPage,'export function TeacherMonthlyReportPrintPage()')!==1) fail('Duplicate TeacherMonthlyReportPrintPage terdeteksi.');

console.log('\n[PASS] Monthly Report PDF/Print visual patch terpasang.');
console.log('FILES CHANGED / CREATED:');
for(const p of [pagePath,cssPath,topAsset,bottomAsset]) console.log(`- ${p}`);
console.log('\nSlip Honor / Invoice / Kwitansi / Supabase tidak disentuh.');
console.log('Lanjutkan: git diff --check && npm run build');
